use super::*;
use crate::money::{money, Currency, Money};

/// Everything the calls are worth together, IF every one lands. Contingent, and it says so.
pub fn total_if_every_ask_lands(cases: &[NegotiationCase], currency: Currency) -> Money {
    money(cases.iter().map(|c| c.annual_value_if_won.minor).sum(), currency)
}
